+fn a_file_button_is_greyed_with_its_reason_in_the_browser() {
+    let mut h = Harness::new_ui(|ui| {
+        let _ = browser_files::button(ui, Some(NEEDS_PICKER), "Load machine (.mch)", "");
+        let _ = browser_files::button(ui, None, "Built-in", "");
