+    h.run();
+    assert!(h.get_by_label("Load machine (.mch)").accesskit_node().is_disabled(), "greyed in the browser");
+    assert!(!h.get_by_label("Built-in").accesskit_node().is_disabled(), "a live button stays live");
+}

